import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.Dp3tugkT.js";const m=JSON.parse('{"title":"Feature Inventory: Distributed URL Shortener Engine","description":"","frontmatter":{},"headers":[],"relativePath":"01-features.md","filePath":"01-features.md"}'),n={name:"01-features.md"};function o(s,e,u,c,d,l){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="feature-inventory-distributed-url-shortener-engine" tabindex="-1">Feature Inventory: Distributed URL Shortener Engine <a class="header-anchor" href="#feature-inventory-distributed-url-shortener-engine" aria-label="Permalink to &quot;Feature Inventory: Distributed URL Shortener Engine&quot;">​</a></h1><h2 id="overview-of-core-features" tabindex="-1">Overview of Core Features <a class="header-anchor" href="#overview-of-core-features" aria-label="Permalink to &quot;Overview of Core Features&quot;">​</a></h2><ul><li><strong>F1: Collision-Resistant Nanoid Slug Generation</strong>: High-entropy 7-character Base62/URL-safe string generation with over 4.3 trillion unique permutations.</li><li><strong>F2: Atomic Redirection &amp; Real-Time Click Telemetry</strong>: Sub-millisecond HTTP 302 redirection with atomic MongoDB <code>$inc</code> click counters that prevent race conditions.</li><li><strong>F3: Custom Vanity Alias &amp; Collision Detection</strong>: Allows registered users to specify customized vanity slugs with database-enforced unique constraints (<code>11000</code> duplicate key handling).</li><li><strong>F4: Secure Cookie-Based JWT Authentication</strong>: Stateless identity verification using httpOnly cookies, password hashing with bcrypt, and contextual <code>req.user</code> injection.</li><li><strong>F5: TanStack Query Server State &amp; Redux Dashboard</strong>: Real-time URL management table with optimistic cache updates, instant clipboard copying, and user history tracking.</li></ul><h2 id="say-it-out-loud-feature-summary" tabindex="-1">Say It Out Loud (Feature Summary) <a class="header-anchor" href="#say-it-out-loud-feature-summary" aria-label="Permalink to &quot;Say It Out Loud (Feature Summary)&quot;">​</a></h2><p>&quot;When presenting this project, I highlight the balance between speed and data integrity. On one hand, redirection must be blisteringly fast—which I achieve through single-hop indexed database lookups and HTTP 302 redirects. On the other hand, analytics must be completely accurate, so I implemented atomic increments at the database layer rather than separate read-and-write passes that could cause race conditions under high concurrency.&quot;</p>',5)])])}const g=t(n,[["render",o]]);export{m as __pageData,g as default};
